PAGE=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Panther Peptides | Jarvis</title><style>:root{--bg:#050b13;--p:#0d1b2d;--line:#294765;--t:#f2f7ff;--m:#93abc3;--g:#35d39a;--r:#ff7185;--a:#f0b64b;--b:#4b9dff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -15%,#183a61,#07111f 40%,#040910);color:var(--t);font:15px system-ui;min-height:100vh}.w{max-width:1500px;margin:auto;padding:18px}.top,.row,.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.top{justify-content:space-between}.logo{width:50px;height:50px;border-radius:15px;background:linear-gradient(135deg,#4b9dff,#53dfc0);display:grid;place-items:center;color:#05101d;font-weight:900}h1,h2,h3{margin:0}.muted{color:var(--m)}.card{background:linear-gradient(180deg,#102138,#091626);border:1px solid var(--line);border-radius:18px;padding:18px}.btn{border:1px solid #315779;background:#10243d;color:white;padding:11px 14px;border-radius:11px;font-weight:750;cursor:pointer}.primary{background:#174d8b}.yes{background:#123d32}.no{background:#431b25}.field{width:100%;background:#06111f;border:1px solid #315779;color:white;border-radius:11px;padding:13px}.strategy{display:grid;grid-template-columns:1fr auto auto;gap:10px;margin:15px 0}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:15px 0}.metric b{display:block;font-size:25px}.grid{display:grid;grid-template-columns:1.35fr .85fr;gap:15px}.event{border:1px solid #203b57;border-radius:12px;padding:11px;margin-top:8px;background:#081522}.pill{display:inline-block;border:1px solid #365a7c;border-radius:999px;padding:5px 9px;font-size:12px}.online,.completed,.connected,.available{color:#bdf5df;border-color:#286b59}.blocked,.disconnected{color:#ffabb8;border-color:#8c3448}.running{color:#b9dcff;border-color:#3b6f9d}.queued,.awaiting_approval{color:#ffdc91;border-color:#8a6723}.tabs{display:flex;gap:8px;margin:14px 0;overflow:auto}.tab.active{outline:2px solid #4b9dff}.hidden{display:none}.banner,.notice{margin:14px 0;padding:11px 14px;border-radius:12px}.banner{border:1px solid #285f51;background:#0d2923;color:#c8f5e4}.notice{border:1px solid #8a6723;background:#2a2110;color:#ffdc91}.approval{border:2px solid var(--a);margin:15px 0}.login{max-width:500px;margin:8vh auto}.integration{display:grid;grid-template-columns:1fr auto;gap:10px}.detail{white-space:pre-wrap;font-size:13px;max-height:180px;overflow:auto}.formgrid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 2fr auto;gap:8px;margin:12px 0}.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:700px}th,td{padding:10px;border-bottom:1px solid #1d354e;text-align:left}.sectionhead{display:flex;justify-content:space-between;align-items:center;gap:10px}.voice{border-color:#4b9dff}.voice.on{background:#174d8b}@media(max-width:900px){.w{padding:10px}.metrics{grid-template-columns:repeat(2,1fr)}.grid,.strategy,.formgrid{grid-template-columns:1fr}.btn{min-height:44px}}</style></head><body><div class="w"><header class="top"><div class="row"><div class="logo">PP</div><div><h1>Panther Peptides</h1><div class="muted">Jarvis Business Operating System · <span id="ver">starting</span> · release <b>USE-NOW-240</b></div></div></div><div class="actions"><span id="state" class="pill queued">Starting…</span><button class="btn" onclick="load()">Refresh</button><button id="logout" class="btn hidden" onclick="doLogout()">Logout</button></div></header><div id="notice" class="notice hidden"></div><div id="login" class="card login"><h2>Owner Access</h2><p class="muted">Authenticate to load the business operating dashboard.</p><input id="pw" class="field" type="password" placeholder="Owner password" onkeydown="if(event.key==='Enter')doLogin()"><p><button class="btn primary" onclick="doLogin()">Open Jarvis</button></p><p id="err"></p></div><main id="app" class="hidden"><div class="banner">OPERATING MODE — Manage the business here. Jarvis executes through connected systems, tracks work, preserves business knowledge and inventory, records evidence, and surfaces owner decisions.</div><section id="approval" class="card approval hidden"></section><div class="strategy"><input id="objective" class="field" placeholder="Tell Jarvis the business outcome you want" onkeydown="if(event.key==='Enter')runObjective()"><button class="btn voice" id="mic" onclick="voiceInput()">🎙 Voice</button><button class="btn primary" onclick="runObjective()">Run Objective</button></div><div id="metrics" class="metrics"></div><div class="tabs"><button class="btn tab active" onclick="tab('home',this)">Command Center</button><button class="btn tab" onclick="tab('inventory',this)">Inventory</button><button class="btn tab" onclick="tab('tasks',this)">Business Tasks</button><button class="btn tab" onclick="tab('knowledge',this)">Knowledge</button><button class="btn tab" onclick="tab('notes',this)">Notes & Decisions</button><button class="btn tab" onclick="tab('systems',this)">Integrations</button><button class="btn tab" onclick="tab('history',this)">Action History</button></div><section id="home" class="grid"><div class="card"><h2>Active & Recent Objectives</h2><div id="objectives"></div></div><div class="card"><h2>Live Activity</h2><div id="activity"></div></div></section><section id="inventory" class="card hidden"><div class="sectionhead"><div><h2>Inventory</h2><div class="muted">Available, held and quarantined stock.</div></div></div><div class="formgrid"><input id="ip" class="field" placeholder="Product"><input id="il" class="field" placeholder="Lot"><input id="iq" class="field" type="number" placeholder="Qty"><select id="is" class="field"><option>available</option><option>held</option><option>quarantine</option><option>sold</option></select><input id="in" class="field" placeholder="Notes"><button class="btn primary" onclick="saveInventory()">Add / Update</button></div><div class="table"><table><thead><tr><th>Product</th><th>Lot</th><th>Qty</th><th>Status</th><th>COA</th><th>Notes</th><th></th></tr></thead><tbody id="invrows"></tbody></table></div></section><section id="tasks" class="card hidden"><h2>Persistent Business Tasks</h2><p class="muted">Work Jarvis creates and tracks across objectives.</p><div id="tasklist"></div></section><section id="knowledge" class="card hidden"><h2>Jarvis Knowledge</h2><p class="muted">Upload SOPs, supplier information, product references, CSVs, PDFs and operating documents. Files persist on the Jarvis disk.</p><form onsubmit="uploadKnowledge(event)"><div class="formgrid"><input id="kf" class="field" type="file" required><input id="kc" class="field" placeholder="Category"><input id="kt" class="field" placeholder="Tags"><button class="btn primary">Upload</button></div></form><div id="knowlist"></div></section><section id="notes" class="card hidden"><h2>Business Notes & Decisions</h2><div class="formgrid"><input id="nt" class="field" placeholder="Title"><input id="nc" class="field" placeholder="Category"><input id="nn" class="field" placeholder="Decision / note"><button class="btn primary" onclick="saveNote()">Save</button></div><div id="notelist"></div></section><section id="systems" class="card hidden"><h2>Business Systems</h2><p class="muted">Connected means Jarvis has a live operating path. Not connected is a real capability gap—not something Jarvis will pretend to do.</p><div id="integrations"></div></section><section id="history" class="card hidden"><h2>Verified Action History</h2><div id="historylist"></div></section></main></div><script>const $=x=>document.getElementById(x);let D=null,A=null;const e=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));async function req(u,o={}){let r=await fetch(u,{...o,cache:'no-store'}),d=await r.json().catch(()=>({}));if(!r.ok){let x=Error(d.detail||d.error||('HTTP '+r.status));x.status=r.status;throw x}return d}function note(t){$('notice').textContent=t;$('notice').classList.toggle('hidden',!t)}async function doLogin(){try{await req('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('pw').value})});$('pw').value='';await load()}catch(x){$('err').textContent=x.message}}async function doLogout(){await fetch('/api/logout',{method:'POST'});location.reload()}function tab(id,b){['home','inventory','tasks','knowledge','notes','systems','history'].forEach(x=>$(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active')}function pill(s){return `<span class="pill ${e(s)}">${e(s)}</span>`}async function load(){try{D=await req('/api/dashboard');$('login').classList.add('hidden');$('app').classList.remove('hidden');$('logout').classList.remove('hidden');$('ver').textContent='v'+D.version;let r=D.operator;$('state').textContent=r.worker_alive?'Jarvis online':'Runtime attention';$('state').className='pill '+(r.worker_alive?'online':'blocked');render()}catch(x){if(x.status===401){$('login').classList.remove('hidden');$('app').classList.add('hidden')}else note('Dashboard connection problem: '+x.message)}}function render(){let r=D.operator,iv=D.inventory_summary||{};$('metrics').innerHTML=[['Running',r.running],['Queued',r.queued],['Approvals',r.awaiting_approval],['Available units',iv.available_units||0],['Held units',iv.held_units||0],['Connected systems',(D.integrations||[]).filter(x=>x.status==='connected').length]].map(x=>`<div class="card metric"><span class="muted">${x[0]}</span><b>${x[1]}</b></div>`).join('');$('objectives').innerHTML=(D.objectives||[]).slice(0,20).map(x=>`<div class="event"><b>#${x.id} ${e(x.title)}</b><div>${pill(x.state)} · step ${x.step}</div>${x.result?`<div class="muted">${e(x.result)}</div>`:''}${x.blocked_reason?`<div class="muted">Blocked: ${e(x.blocked_reason)}</div>`:''}</div>`).join('')||'<p class="muted">No objectives yet.</p>';$('activity').innerHTML=(D.activity||[]).slice(0,10).map(x=>`<div class="event"><b>${e(x.tool||x.kind)} · ${e(x.status)}</b><div class="muted">#${x.objective_id} ${e(x.objective_title||'')}</div></div>`).join('')||'<p class="muted">No activity yet.</p>';$('tasklist').innerHTML=(D.tasks||[]).map(x=>`<div class="event"><b>${e(x.title)}</b> ${pill(x.status)}<div class="muted">${e(x.notes||'')}</div></div>`).join('')||'<p class="muted">No persistent tasks.</p>';$('integrations').innerHTML=(D.integrations||[]).map(x=>`<div class="event integration"><div><b>${e(x.name)}</b><div class="muted">${e(x.detail)}</div></div>${pill(x.status)}</div>`).join('');$('historylist').innerHTML=(D.activity||[]).map(x=>`<div class="event"><b>${e(x.kind)} · ${e(x.tool||'system')} · ${e(x.status)}</b><div class="muted">Objective #${x.objective_id} · cycle ${x.cycle}</div><div class="detail muted">${e(x.detail||'')}</div></div>`).join('')||'<p class="muted">No recorded actions.</p>';$('invrows').innerHTML=(D.inventory||[]).map(x=>`<tr><td><b>${e(x.product)}</b></td><td>${e(x.lot||'—')}</td><td>${e(x.quantity)}</td><td>${pill(x.status)}</td><td>${e(x.coa_status)}</td><td>${e(x.notes||'')}</td><td><button class="btn no" onclick="delInventory(${x.id})">Delete</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No inventory entered.</td></tr>';$('knowlist').innerHTML=(D.knowledge||[]).map(x=>`<div class="event"><b>${e(x.name)}</b><div class="muted">${e(x.category||'general')} · ${Number(x.size_bytes||0).toLocaleString()} bytes · ${e(x.tags||'')}</div></div>`).join('')||'<p class="muted">No knowledge files yet.</p>';$('notelist').innerHTML=(D.notes||[]).map(x=>`<div class="event"><b>${e(x.title)}</b> ${pill(x.category)}<div class="muted">${e(x.note)}</div></div>`).join('')||'<p class="muted">No business notes yet.</p>';A=D.approval;$('approval').classList.toggle('hidden',!A);if(A)$('approval').innerHTML=`<div class="muted">JARVIS NEEDS ONE DECISION</div><h2>${e(A.objective_title||'Owner approval')}</h2><p>${e(A.question)}</p><div class="actions"><button class="btn yes" onclick="decide(true)">✓ APPROVE</button><button class="btn no" onclick="decide(false)">✕ DENY</button></div>`}async function decide(ok){if(!A)return;await req('/api/approvals/'+A.id,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approved:ok})});load()}async function runObjective(){let t=$('objective').value.trim();if(!t)return;$('objective').value='';try{let d=await req('/api/objectives',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({objective:t,priority:50})});note('Objective #'+d.objective_id+' queued. Jarvis is working it.');setTimeout(load,700)}catch(x){note('Could not queue objective: '+x.message)}}async function saveInventory(){let p=$('ip').value.trim();if(!p)return note('Product is required.');await req('/api/inventory',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({product:p,lot:$('il').value.trim(),quantity:Number($('iq').value||0),status:$('is').value,notes:$('in').value.trim()})});['ip','il','iq','in'].forEach(x=>$(x).value='');load()}async function delInventory(id){await req('/api/inventory/'+id,{method:'DELETE'});load()}async function uploadKnowledge(ev){ev.preventDefault();let f=new FormData();f.append('file',$('kf').files[0]);f.append('category',$('kc').value||'general');f.append('tags',$('kt').value||'');await req('/api/knowledge',{method:'POST',body:f});ev.target.reset();load()}async function saveNote(){let t=$('nt').value.trim(),n=$('nn').value.trim();if(!t||!n)return note('Title and note are required.');await req('/api/notes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:t,note:n,category:$('nc').value||'general'})});['nt','nn','nc'].forEach(x=>$(x).value='');load()}function voiceInput(){let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return note('Voice dictation is not supported by this browser.');let r=new SR();r.lang='en-US';r.interimResults=false;$('mic').classList.add('on');$('mic').textContent='Listening…';r.onresult=x=>{$('objective').value=x.results[0][0].transcript};r.onend=()=>{$('mic').classList.remove('on');$('mic').textContent='🎙 Voice'};r.onerror=()=>note('Voice input could not start. Check browser microphone permission.');r.start()}load();setInterval(()=>{if(!$('app').classList.contains('hidden'))load()},4000)</script></body></html>'''
